import React, { useState, useEffect, useRef } from 'react';
import AuraCanvas from '../components/AuraCanvas';

const PHASES = [
  { name:'Andas in',  seconds:4,  hues:[195,215], intensity:0.5,  speed:0.15, label:'Djupt in genom näsan' },
  { name:'Håll',      seconds:7,  hues:[210,228], intensity:0.45, speed:0.06, label:'Håll andan stilla' },
  { name:'Andas ut',  seconds:8,  hues:[175,195], intensity:0.55, speed:0.18, label:'Sakta ut genom munnen' },
];
const TOTAL = 4;

export default function Breathing({ setPage }) {
  const [running, setRunning] = useState(false);
  const [done,    setDone]    = useState(false);
  const [phase,   setPhase]   = useState(0);
  const [count,   setCount]   = useState(0);
  const [cycle,   setCycle]   = useState(0);
  const [orbScale, setOrbScale] = useState(1);
  const timer = useRef(null);

  const runPhase = (pi, ci) => {
    if (ci >= TOTAL) { setRunning(false); setDone(true); return; }
    setPhase(pi); setCycle(ci); setCount(PHASES[pi].seconds);
    if (pi === 0) setOrbScale(1.6);
    else if (pi === 1) setOrbScale(1.6);
    else setOrbScale(0.7);
    let c = PHASES[pi].seconds;
    timer.current = setInterval(() => {
      c--; setCount(c);
      if (c <= 0) { clearInterval(timer.current); const np = (pi+1)%3; setTimeout(() => runPhase(np, np===0?ci+1:ci), 400); }
    }, 1000);
  };
  const start = () => { setRunning(true); setDone(false); setOrbScale(1); runPhase(0, 0); };
  useEffect(() => () => clearInterval(timer.current), []);
  const cur = PHASES[phase];

  if (done) return (
    <div style={{ position:'relative', height:'100vh', overflow:'hidden', background:'#0d0d0d' }}>
      <AuraCanvas hues={[155,175]} intensity={0.6} speed={0.5} />
      <div style={{ position:'absolute', inset:0, zIndex:10, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', textAlign:'center', padding:'0 32px' }}>
        <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(240,237,230,0.35)', marginBottom:16 }}>{TOTAL} omgångar · klart</p>
        <h2 style={{ fontSize:'clamp(32px,8vw,50px)', fontWeight:700, letterSpacing:'-0.04em', color:'#f0ede6', marginBottom:10 }}>Bra jobbat</h2>
        <p style={{ fontSize:14, color:'rgba(240,237,230,0.45)', marginBottom:36, fontWeight:300, maxWidth:260 }}>Ditt nervsystem har lugnat ner sig.</p>
        <div style={{ display:'flex', gap:10 }}>
          <button onClick={()=>setPage('checkin')} style={{ padding:'13px 24px', borderRadius:100, background:'rgba(240,237,230,0.9)', color:'#0d0d0d', fontSize:13, fontWeight:600, border:'none' }}>Check-in →</button>
          <button onClick={()=>{setDone(false);setRunning(false);setOrbScale(1);}} style={{ padding:'13px 24px', borderRadius:100, background:'rgba(255,255,255,0.08)', border:'1px solid rgba(255,255,255,0.12)', color:'rgba(240,237,230,0.6)', fontSize:13 }}>Igen</button>
        </div>
      </div>
    </div>
  );

  return (
    <div style={{ position:'relative', height:'100vh', overflow:'hidden', background:'#0d0d0d' }}>
      {/* Aura canvas — the breathing visual */}
      <div style={{
        position:'absolute', inset:0,
        transition: running
          ? phase===0 ? `transform ${PHASES[0].seconds}s linear`
          : phase===1 ? 'transform .8s ease'
          : `transform ${PHASES[2].seconds}s linear`
          : 'transform 1.5s cubic-bezier(0.16,1,0.3,1)',
        transform:`scale(${orbScale})`,
        transformOrigin:'center center',
      }}>
        <AuraCanvas hues={running ? cur.hues : [195,215]} intensity={running ? cur.intensity : 0.45} speed={running ? cur.speed : 0.25} />
      </div>

      {/* Vignette */}
      <div style={{ position:'absolute', inset:0, background:'radial-gradient(circle at center, transparent 30%, rgba(13,13,13,0.5) 100%)', pointerEvents:'none', zIndex:1 }} />

      {/* UI */}
      <div style={{ position:'absolute', inset:0, zIndex:10, display:'flex', flexDirection:'column', padding:'28px 22px', paddingBottom:100 }}>

        {/* Phase numbers — top center */}
        <div style={{ textAlign:'center', marginBottom:'auto' }}>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.22em', textTransform:'uppercase', color:'rgba(240,237,230,0.28)', marginBottom:16 }}>4 – 7 – 8</p>
          <div style={{ display:'flex', gap:20, justifyContent:'center' }}>
            {PHASES.map((p, i) => (
              <div key={i} style={{ textAlign:'center' }}>
                <div style={{ fontSize:20, fontWeight:700, color:running&&phase===i?'rgba(240,237,230,0.9)':'rgba(240,237,230,0.2)', transition:'color .5s', letterSpacing:'-0.03em' }}>{p.seconds}</div>
                <div style={{ fontFamily:'DM Mono,monospace', fontSize:8, textTransform:'uppercase', letterSpacing:'0.1em', color:running&&phase===i?'rgba(240,237,230,0.5)':'rgba(240,237,230,0.15)', marginTop:2, transition:'color .5s' }}>{p.name}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Centre — count */}
        {running && (
          <div style={{ position:'absolute', inset:0, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', pointerEvents:'none', zIndex:20 }}>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(240,237,230,0.45)', marginBottom:8 }}>{cur.name}</p>
            <div style={{ fontSize:80, fontWeight:700, color:'rgba(240,237,230,0.85)', lineHeight:1, letterSpacing:'-0.05em' }}>{count}</div>
            <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(240,237,230,0.28)', marginTop:10 }}>{cycle+1} / {TOTAL}</p>
          </div>
        )}

        {/* Bottom */}
        <div>
          {running ? (
            <div style={{ background:'rgba(13,13,13,0.6)', backdropFilter:'blur(20px)', borderRadius:18, padding:'13px 18px', textAlign:'center', border:'1px solid rgba(255,255,255,0.07)' }}>
              <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.14em', textTransform:'uppercase', color:'rgba(240,237,230,0.4)' }}>{cur.label}</p>
            </div>
          ) : (
            <>
              <h1 style={{ fontSize:'clamp(30px,7vw,44px)', fontWeight:700, letterSpacing:'-0.04em', color:'#f0ede6', marginBottom:10, lineHeight:1.05 }}>
                Andningsövning
              </h1>
              <p style={{ fontSize:13, color:'rgba(240,237,230,0.4)', fontWeight:300, lineHeight:1.75, marginBottom:20 }}>
                Aktiverar det parasympatiska nervsystemet. 4 minuter.
              </p>
              <button onClick={start} style={{ width:'100%', padding:'15px', borderRadius:100, background:'rgba(240,237,230,0.9)', color:'#0d0d0d', fontSize:14, fontWeight:700, border:'none', boxShadow:'0 8px 40px rgba(0,0,0,0.4)' }}>
                Starta →
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}
